#include <iostream>
#include <utility>
struct A {
  A() { std::cout << "A()\n"; }
  A(const A&) { std::cout << "A(const A&)\n"; }
  A(A&&) { std::cout << "A(A&&)\n"; }
  ~A() { std::cout << "~A()\n"; }
};
template <typename T>
void perfectForward(T&& param) {
  A a = std::forward<T>(param); //std::forward is crucial here
}
int main() {
  A a;
  perfectForward(a); // lvalue, calls A(const A&)
  perfectForward(A()); // rvalue, calls A(A&&)
  return 0;
}
